def transform(grid):
    # The scattered bars encode the compact output: 3-bar lengths form row one;
    # the two 3-cells in the shortest bar frame the single 2-marker row.
    seen=set(); bars=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v in (2,3) and (r,c) not in seen:
                cells=[(r,c)]; seen.add((r,c))
                for rr,cc in cells:
                    for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                        if 0<=nr<len(grid) and 0<=nc<len(row) and (nr,nc) not in seen and grid[nr][nc]==v:
                            seen.add((nr,nc)); cells.append((nr,nc))
                bars.append((v,len(cells)))
    threes=[n for v,n in bars if v==3]
    twos=[n for v,n in bars if v==2]
    width=max(threes)
    return [[3]*width,[3,2]+[0]*(width-2)]
