def transform(grid):
    counts = {2: 0, 3: 0}
    for row in grid:
        c = 0
        while c < len(row):
            color = row[c]
            if color in counts:
                counts[color] += 1
                while c < len(row) and row[c] == color:
                    c += 1
            else:
                c += 1
    vals = [3] * counts[3] + [2] * counts[2]
    vals = (vals + [0] * 6)[:6]
    return [vals[:3], vals[3:]]
